create extension if not exists pgcrypto;create table if not exists public.site_sections(id uuid primary key default gen_random_uuid(),eyebrow text not null default 'INFORMATION',title text not null,body text not null,icon text not null default 'medical',sort_order integer not null default 10,is_published boolean not null default true,created_at timestamptz not null default now());create table if not exists public.site_admins(user_id uuid primary key references auth.users(id) on delete cascade);alter table public.site_sections enable row level security;alter table public.site_admins enable row level security;revoke all on public.site_admins from anon,authenticated;revoke all on public.site_sections from anon,authenticated;